// check_availability — lecture directe du datetime sans OpenAI
// Fix timezone : VPS en UTC, datetime ElevenLabs sans timezone = heure Paris
const body = $input.first().json;
const params = body.parameters ?? body;
const toolCallId = body.tool_call_id ?? body.id ?? 'unknown';

const datetimeRaw = params.datetime ?? '';
if (!datetimeRaw) throw new Error('datetime manquant dans les params');

// Detecte le decalage Paris/UTC dynamiquement (gere heure ete/hiver)
function parisToUTC(dtStr) {
  if (dtStr.endsWith('Z') || /[+-]\d{2}:\d{2}$/.test(dtStr)) {
    return new Date(dtStr).toISOString(); // deja avec timezone
  }
  // Pas de timezone = heure Paris. Calcul decalage actuel.
  const now = new Date();
  const parisMs = Date.parse(now.toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
  const utcMs   = Date.parse(now.toLocaleString('en-US', { timeZone: 'UTC' }));
  const offsetMs = parisMs - utcMs; // ex: +7200000 en ete (UTC+2)
  // dtStr parse comme UTC (9h UTC), on soustrait l'offset pour obtenir vrai UTC (7h UTC)
  return new Date(new Date(dtStr + 'Z').getTime() - offsetMs).toISOString();
}

const dureeMin = parseInt(params.duree_minutes ?? 60);
const startISO = parisToUTC(datetimeRaw);
const endISO   = new Date(new Date(startISO).getTime() + dureeMin * 60000).toISOString();

const dateLisible = new Date(startISO).toLocaleString('fr-FR', {
  weekday: 'long', day: 'numeric', month: 'long',
  hour: '2-digit', minute: '2-digit',
  timeZone: 'Europe/Paris'
});

return [{
  json: {
    toolCallId,
    mode: 'check_availability',
    nomClient:   params.nom_client   ?? params.name  ?? 'Client',
    emailClient: params.email_client ?? params.email ?? null,
    tel:         params.telephone    ?? params.phone ?? null,
    description: params.description  ?? 'Rendez-vous',
    dateTimeStart: startISO,
    dateTimeEnd:   endISO,
    dureeMin,
    dateLisible,
  }
}];

// check_next_slots — prepare le prompt OpenAI avec heure Paris correcte
const body = $input.first().json;
const params = body.parameters ?? body;
const toolCallId = body.tool_call_id ?? body.id ?? 'unknown';

// Heure Paris pour le prompt
const nowParis = new Date().toLocaleString('fr-FR', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
  hour: '2-digit', minute: '2-digit',
  timeZone: 'Europe/Paris'
});

const rawInput = JSON.stringify(params);

return [{
  json: {
    toolCallId,
    mode: 'check_next_slots',
    rawParams: params,
    nomClient:   params.nom_client   ?? null,
    emailClient: params.email_client ?? null,
    tel:         params.telephone    ?? null,
    description: params.description  ?? 'Rendez-vous',
    promptUser: `Parametres recus : ${rawInput}\n\nDate et heure actuelles a Paris : ${nowParis}\n\nExtrais la plage de dates pour chercher les prochains creneaux (defaut : les 7 prochains jours).`,
  }
}];

