// FIX: search_to_iso absent => default +7 jours (pas +1h)
// FIX: parisToUTC retourne null si dtStr vide — check avant appel
const openaiResp = $input.first().json;
const extracted = JSON.parse(openaiResp.choices[0].message.content);

const prev = $('Preparer prompt — Prochains creneaux').first().json;

function parisToUTC(dtStr) {
  if (!dtStr) return null; // null explicite — pas de valeur par defaut ici
  if (dtStr.endsWith('Z') || /[+-]\d{2}:\d{2}$/.test(dtStr)) return new Date(dtStr).toISOString();
  const now = new Date();
  const parisMs = Date.parse(now.toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
  const utcMs   = Date.parse(now.toLocaleString('en-US', { timeZone: 'UTC' }));
  const offsetMs = parisMs - utcMs;
  return new Date(new Date(dtStr + 'Z').getTime() - offsetMs).toISOString();
}

// search_from absent => now + 1h (acceptable comme borne de depart)
const searchFrom = extracted.search_from_iso
  ? parisToUTC(extracted.search_from_iso)
  : new Date(Date.now() + 3600000).toISOString();

// search_to absent => +7 jours (fenetre par defaut)
const searchTo = extracted.search_to_iso
  ? parisToUTC(extracted.search_to_iso)
  : new Date(Date.now() + 7 * 86400000).toISOString();

return [{
  json: {
    ...prev,
    dateTimeStart: searchFrom,
    dateTimeEnd:   searchTo,
    dureeMin: extracted.duration_minutes ?? 60,
  }
}];

// check_availability : verifie si le creneau est libre
// Inclut timed events ET all-day opaques, exclut les marques 'libre'
const events = $input.all();
const calItems = events.filter(e => {
  if (!e.json.id) return false;
  if (e.json.transparency === 'transparent') return false;
  return true;
});

const ctx = $('Extraire dispo — Direct').first().json;

const creneaux = calItems.map(e => ({
  titre: e.json.summary ?? '(sans titre)',
  debut: e.json.start.dateTime ?? e.json.start.date,
  fin:   e.json.end.dateTime   ?? e.json.end.date,
}));

const isAvailable = creneaux.length === 0;

// Sauvegarde le creneau si disponible (pour create_event)
if (isAvailable) {
  const staticData = $getWorkflowStaticData('global');
  staticData.pendingSlot = {
    dateTimeStart: ctx.dateTimeStart,
    dateTimeEnd:   ctx.dateTimeEnd,
    dateLisible:   ctx.dateLisible,
    nomClient:     ctx.nomClient,
    description:   ctx.description,
    savedAt:       new Date().toISOString(),
  };
}

return [{
  json: {
    ...ctx,
    isAvailable,
    conflits: creneaux,
    nbConflits: creneaux.length,
  }
}];

// check_next_slots : trouve les creneaux libres (9h-18h, lun-ven)
const events = $input.all();
const calItems = events.filter(e => {
  if (!e.json.id) return false;
  if (e.json.transparency === 'transparent') return false;
  if (!e.json.start.dateTime) return false; // all-day non pris en compte ici
  return true;
});

const ctx = $('Parser resultat — Prochains creneaux').first().json;
const dureeMs = (ctx.dureeMin || 60) * 60 * 1000;

const busySlots = calItems.map(e => ({
  start: new Date(e.json.start.dateTime).getTime(),
  end:   new Date(e.json.end.dateTime).getTime(),
})).sort((a, b) => a.start - b.start);

const searchFrom = ctx.dateTimeStart ? new Date(ctx.dateTimeStart) : new Date();
const searchTo   = ctx.dateTimeEnd   ? new Date(ctx.dateTimeEnd)   : new Date(Date.now() + 7 * 86400000);

const freeSlots = [];
let cursor = new Date(searchFrom);
cursor.setSeconds(0, 0);

while (cursor < searchTo && freeSlots.length < 5) {
  const dow = cursor.getDay();
  if (dow !== 0 && dow !== 6) {
    const dayStart = new Date(cursor); dayStart.setHours(9, 0, 0, 0);
    const dayEnd   = new Date(cursor); dayEnd.setHours(18, 0, 0, 0);
    let slotStart = Math.max(dayStart.getTime(), Date.now() + 3600000);
    const dayBusy = busySlots.filter(b => b.end > dayStart.getTime() && b.start < dayEnd.getTime());
    for (const busy of dayBusy) {
      if (slotStart + dureeMs <= busy.start && slotStart + dureeMs <= dayEnd.getTime()) {
        freeSlots.push(new Date(slotStart));
        if (freeSlots.length >= 5) break;
      }
      if (busy.end > slotStart) slotStart = busy.end;
    }
    if (freeSlots.length < 5 && slotStart + dureeMs <= dayEnd.getTime()) {
      freeSlots.push(new Date(slotStart));
    }
  }
  cursor.setDate(cursor.getDate() + 1);
  cursor.setHours(0, 0, 0, 0);
}

const fmt = (d) => new Date(d).toLocaleString('fr-FR', {
  weekday: 'long', day: 'numeric', month: 'long',
  hour: '2-digit', minute: '2-digit',
  timeZone: 'Europe/Paris'
});

return [{
  json: {
    ...ctx,
    isAvailable: freeSlots.length > 0,
    freeSlots: freeSlots.map(d => ({ iso: d.toISOString(), lisible: fmt(d) })),
  }
}];

const ctx = $input.first().json;
const message = `Oui, le creneau du ${ctx.dateLisible} est disponible. Souhaitez-vous que je confirme le rendez-vous ?`;
return [{ json: { toolCallId: ctx.toolCallId, result: message } }];

const ctx = $input.first().json;
const conflitsDesc = (ctx.conflits || []).slice(0, 2).map(c => {
  const d = new Date(c.debut).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Paris' });
  const f = new Date(c.fin).toLocaleTimeString('fr-FR',   { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Paris' });
  return `${c.titre} (${d}-${f})`;
}).join(', ');
const message = conflitsDesc
  ? `Je suis desole, ce creneau n'est pas disponible : ${conflitsDesc}. Souhaitez-vous que je vous propose d'autres horaires ?`
  : `Je suis desole, ce creneau n'est pas disponible. Souhaitez-vous que je vous propose d'autres horaires ?`;
return [{ json: { toolCallId: ctx.toolCallId, result: message } }];

const ctx = $input.first().json;
const slots = ctx.freeSlots || [];
const slotsList = slots.map((s, i) => `${i + 1}. ${s.lisible}`).join('. ');
const message = `Voici les prochains creneaux disponibles : ${slotsList}. Lequel vous conviendrait ?`;
return [{ json: { toolCallId: ctx.toolCallId, result: message } }];

const ctx = $input.first().json;
const message = `Je suis desole, je ne trouve pas de creneau disponible dans la periode demandee. Souhaitez-vous chercher sur une periode plus longue ou me donner une date precise ?`;
return [{ json: { toolCallId: ctx.toolCallId, result: message } }];

// FIX: fallback params.start/params.end si pendingSlot absent
// Permet create_event direct avec datetime sans passer par check_availability
const body = $input.first().json;
const params = body.parameters ?? body;
const toolCallId = body.tool_call_id ?? body.id ?? 'unknown';

const staticData = $getWorkflowStaticData('global');
const pending = staticData.pendingSlot || {};

function parisToUTC(dtStr) {
  if (!dtStr) return null;
  if (dtStr.endsWith('Z') || /[+-]\d{2}:\d{2}$/.test(dtStr)) return new Date(dtStr).toISOString();
  const now = new Date();
  const parisMs = Date.parse(now.toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
  const utcMs   = Date.parse(now.toLocaleString('en-US', { timeZone: 'UTC' }));
  return new Date(new Date(dtStr + 'Z').getTime() - (parisMs - utcMs)).toISOString();
}

// Priorite : params.datetime > params.start > pendingSlot.dateTimeStart
const startISO = parisToUTC(params.datetime)
  ?? parisToUTC(params.start)
  ?? pending.dateTimeStart
  ?? null;

if (!startISO) throw new Error('Aucune date exploitable — fournir datetime, start, ou appeler check_availability en premier');

const dureeMin = parseInt(params.duree_minutes ?? 60);

// endISO : pendingSlot > params.end > calcul depuis start
const endISO = pending.dateTimeEnd
  ?? parisToUTC(params.end)
  ?? new Date(new Date(startISO).getTime() + dureeMin * 60000).toISOString();

const dateLisible = pending.dateLisible ?? new Date(startISO).toLocaleString('fr-FR', {
  weekday: 'long', day: 'numeric', month: 'long',
  hour: '2-digit', minute: '2-digit',
  timeZone: 'Europe/Paris'
});

delete staticData.pendingSlot;

return [{
  json: {
    toolCallId,
    nomClient:   params.nom_client   ?? params.name  ?? pending.nomClient  ?? 'Client',
    emailClient: params.email_client ?? params.email ?? null,
    tel:         params.telephone    ?? params.phone ?? null,
    description: params.description  ?? pending.description ?? 'Rendez-vous',
    dateTimeStart: startISO,
    dateTimeEnd:   endISO,
    dateLisible,
  }
}];
